import{_ as s,o as a,c as e,a2 as p}from"./chunks/framework.CqGPl1zp.js";const n="/newx-doc/assets/%E6%95%B0%E6%8D%AE%E6%9D%83%E9%99%90%E6%96%B0%E5%A2%9E-%E8%B4%9F%E8%B4%A3%E4%BA%BA.D4uTMlxh.png",t="data:image/png;base64,",E="/newx-doc/assets/%E6%95%B0%E6%8D%AE%E6%9D%83%E9%99%90%E8%BD%AC%E7%A7%BB-%E8%B4%9F%E8%B4%A3%E4%BA%BA2.B4EZkPrT.png",h="/newx-doc/assets/%E6%95%B0%E6%8D%AE%E6%9D%83%E9%99%90%E6%96%B0%E5%A2%9E-%E8%AF%BB%E5%86%99.Fe5ZMRaO.png",l="/newx-doc/assets/%E6%95%B0%E6%8D%AE%E6%9D%83%E9%99%90%E6%96%B0%E5%A2%9E-%E8%AF%BB%E5%86%992.4YUGIJa-.png",r="/newx-doc/assets/CrmPermission%E6%B3%A8%E8%A7%A3.U2WOh4nj.png",d="/newx-doc/assets/CrmPermission%E6%B3%A8%E8%A7%A3%E4%BD%BF%E7%94%A8%E7%A4%BA%E4%BE%8B.B1AxFLhD.png",k="/newx-doc/assets/CrmPermissionAspect%E7%B1%BB.ChZM3TVk.png",o="/newx-doc/assets/CRM%E7%AE%A1%E7%90%86%E5%91%98.I5moz6Ps.png",A="/newx-doc/assets/%E6%9F%A5%E8%AF%A2%E8%BF%87%E6%BB%A4.D4rSgIXj.png",c="/newx-doc/assets/CrmPermissionUtils%E7%B1%BB.BqYdHuA1.png",g="/newx-doc/assets/CRM%E5%9C%BA%E6%99%AF.B1G8Whfx.png",y=JSON.parse('{"title":"【通用】数据权限","description":"","frontmatter":{},"headers":[],"relativePath":"crm/permission.md","filePath":"crm/permission.md","lastUpdated":null}'),C={name:"crm/permission.md"};function B(m,i,I,F,T,D){return a(),e("div",null,[...i[0]||(i[0]=[p('<h1 id="【通用】数据权限" tabindex="-1">【通用】数据权限 <a class="header-anchor" href="#【通用】数据权限" aria-label="Permalink to &quot;【通用】数据权限&quot;">​</a></h1><p>数据权限，由 <code>yudao-module-crm</code> 后端模块的 <code>permission</code> 包实现，支持某个人对某个数据（线索、客户、商机、合同等等），有对应的权限。</p><p>目前权限由 CrmPermissionLevelEnum 枚举，包括 3 种：<code>OWNER</code>（负责人）、<code>WRITE</code>（读写）、<code>READ</code>（只读），并且 <code>OWNER &gt; WRITE &gt; READ</code>。</p><p>友情提示：</p><p>为什么不使用全局封装的 [《数据权限》])(/data-permission) 呢？</p><p>目前 CRM 系统的数据权限比较灵活，部分功能无法很好的支持。例如说：</p><ul><li>全局的数据权限，只支持对某个数据的操作权限，而 CRM 需要分 OWNER、WRITE、READ 三种权限</li><li>全局的数据全量，对关联数据的权限控制，无法很好的支持。例如说：对某个客户有 WRITE 权限时，可以 WRITE 它下面的联系人、商机、合同等等</li></ul><p>你可以理解全局的数据权限是基于 DB（DAO）层面实现的，而 CRM 的数据权限是基于 Service 层面实现的。</p><h2 id="_1-表结构" tabindex="-1">1. 表结构 <a class="header-anchor" href="#_1-表结构" aria-label="Permalink to &quot;1. 表结构&quot;">​</a></h2><blockquote><p>省略 creator/create_time/updater/update_time/deleted/tenant_id 等通用字段</p></blockquote><div class="language-SQL vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">SQL</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CREATE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> TABLE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> `</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">crm_permission</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">` (</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `id`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> bigint</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> AUTO_INCREMENT COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;编号&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `user_id`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> bigint</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> DEFAULT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;0&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;用户编号&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `biz_type`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> tinyint</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> DEFAULT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;100&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;数据类型&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `biz_id`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> bigint</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> DEFAULT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;0&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;数据编号&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `level`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> int</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> DEFAULT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;0&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;会员等级&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  PRIMARY KEY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`id`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">USING</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> BTREE</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) ENGINE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">InnoDB AUTO_INCREMENT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">86</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> DEFAULT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> CHARSET</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">utf8mb4 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">COLLATE=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">utf8mb4_unicode_ci COMMENT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;CRM 数据权限表&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>基本就是三要素：</p><ul><li>人：<code>user_id</code> 字段</li><li>数据：<code>biz_type</code> + <code>biz_id</code> 字段。其中 <code>biz_type</code> 由 CrmBizTypeEnum 枚举，包括线索、客户、联系人、商机、合同、回款等等</li><li>权限：<code>level</code> 字段。由 CrmPermissionLevelEnum 枚举，包括 <code>OWNER</code>、<code>WRITE</code>、<code>READ</code> 三种</li></ul><h3 id="_1-1-owner-负责人" tabindex="-1">1.1 <code>OWNER</code> 负责人 <a class="header-anchor" href="#_1-1-owner-负责人" aria-label="Permalink to &quot;1.1 `OWNER` 负责人&quot;">​</a></h3><p>① 每个数据在新增时，会插入一条 <code>OWNER</code> 的权限。例如说，新增一个客户，会插入一条 <code>OWNER</code> 的权限。如下图所示：</p><p><img src="'+n+'" alt="新增 OWNER 负责人（代码）"></p><p>② 每个数据在转移时，会对新、老负责人的权限做不同的处理。例如说，联系人转移给其他人，会更新对应的权限。如下图所示：</p><p><img src="'+t+'" alt="转移 OWNER 负责人（界面）"></p><ul><li>老负责人，会将对应的 <code>crm_permission</code> 的 <code>level</code> 更新为 <code>READ</code></li><li>新负责人，会插入一条 <code>OWNER</code> 的权限</li></ul><p><img src="'+E+'" alt="转移 OWNER 负责人（代码）"></p><h3 id="_1-2-write-读写、read-只读" tabindex="-1">1.2 <code>WRITE</code> 读写、<code>READ</code> 只读 <a class="header-anchor" href="#_1-2-write-读写、read-只读" aria-label="Permalink to &quot;1.2 `WRITE` 读写、`READ` 只读&quot;">​</a></h3><p>在每个数据的详情界面，有一个 [团队成员] 的功能，可以查看当前数据的权限，同时可以修改 <code>WRITE</code> 和 <code>READ</code> 的权限。如下图所示：</p><p><img src="'+h+'" alt="新增读写权限（界面）"></p><p>这是一个通用的功能，不需要每个数据都实现一遍，在 CrmPermissionController 已经统一实现。如下图所示：</p><p><img src="'+l+'" alt="新增读写权限（代码）"></p><p>友情提示：为什么转移负责人不能在 CrmPermissionController 统一实现呢？</p><p>考虑到查询方便，每个数据记录自身会有 <code>owner_user_id</code> 字段，转移时需要更新，所以没一起实现。</p><h2 id="_3-后端实现" tabindex="-1">3. 后端实现 <a class="header-anchor" href="#_3-后端实现" aria-label="Permalink to &quot;3. 后端实现&quot;">​</a></h2><h3 id="_2-1-操作校验" tabindex="-1">2.1 操作校验 <a class="header-anchor" href="#_2-1-操作校验" aria-label="Permalink to &quot;2.1 操作校验&quot;">​</a></h3><p>操作校验，通过 <code>@CrmPermission</code> 注解实现，只要添加在 Service 方法上，即可实现对应的权限校验。</p><p><img src="'+r+'" alt="CrmPermission 注解"></p><p>① 使用示例，如下图所示：</p><p><img src="'+d+'" alt="CrmPermission 注解使用示例"></p><p>② 通过 Spring AOP 实现，可见 CrmPermissionAspect 类，如下图所示：</p><p><img src="'+k+'" alt="CrmPermissionAspect 类"></p><p>通过这个类，我们也可以看出为什么要有 <code>crm_permission</code> 表。如果没有这个表，我们需要查询每个业务的数据，通过它们的字段，判断当前用户是否有权限，这样拓展性比较差。</p><p>③ 【CRM 管理员】的角色枚举是 <code>crm_admin</code>，它和全局的【超级管理员】 <code>super_admin</code> 是分开的。如下图所示：</p><p><img src="'+o+'" alt="CRM 管理员"></p><p>也就是说，把【CRM 管理员】分配给某个人时，可以查询和操作所有 CRM 的数据。</p><h3 id="_2-2-查询过滤" tabindex="-1">2.2 查询过滤 <a class="header-anchor" href="#_2-2-查询过滤" aria-label="Permalink to &quot;2.2 查询过滤&quot;">​</a></h3><p>在数据的列表界面，我们需要在 DB 数据库查询的时候，就将没有 <code>READ</code> 权限的数据过滤掉。</p><p>疑问：为什么不通过类似 <code>@CrmPermission</code> 注解实现呢？</p><p>可以实现，但是会查询特别多没权限的数据到内存中，导致性能比较差。</p><p>这个无法通用实现，目前是每个业务 Mapper 拼接 SQL 实现，通过联表查询 <code>crm_permission</code> 表，进行过滤。如下图所示：</p><p><img src="'+A+'" alt="查询过滤"></p><p>核心的拼接逻辑在 CrmPermissionUtils 的 <code>#appendPermissionCondition(...)</code> 方法里，不是很复杂，可以自己瞅瞅。如下图所示：</p><p><img src="'+c+'" alt="appendPermissionCondition 方法"></p><p>另外，CRM 系统的所有管理界面，都有一个 CrmSceneTypeEnum 枚举，分成 3 种场景：<code>OWNER</code> 我负责的，<code>INVOLVED</code> 我参与的、<code>SUBORDINATE</code> 下属负责的，也是通过上面查询实现的。</p><p><img src="'+g+'" alt="CRM 场景"></p><p>画外音</p><p>看到这里，在回过头看为什么不基于全局的 [《数据权限》])(/data-permission) 实现，是不是有点明白了呢？</p><p>在设计系统的数据权限，我们总是渴望通过全局的、自动化的方式实现。但是，实际上，业务的数据权限是非常复杂的，很难通过全局的方式实现。</p><p>因此，我们需要在业务层面，实现对应的数据权限逻辑。嘿嘿~</p>',53)])])}const N=s(C,[["render",B]]);export{y as __pageData,N as default};
